static inline const int16_t* waveTableFor(uint8_t voice, uint8_t band) {
  if (voice >= WAVE_VOICE_COUNT) voice = 0;
  if (band >= WAVE_BAND_COUNT) band = WAVE_BAND_COUNT - 1;
  return (const int16_t*)pgm_read_ptr(&waveTables[voice][band]);
}

